// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }

    function testFuzz_property(address actor, address newOwner) public {
        vm.assume(actor != address(this) && actor != address(0));
        vm.assume(newOwner != address(0));

        vm.prank(actor);
        try c.transferOwnership(newOwner) {
            // call succeeded: owner must still be unchanged (address(0))
            assertTrue(c.owner() == address(0), "non-owner changed owner");
        } catch {
            // call reverted: owner unchanged
            assertTrue(c.owner() == address(0), "non-owner changed owner");
        }
    }
}
